  socket.setKeepAlive(true, 10000);

  const isAgent = isAgentRoute(req);
  const isSignal = pathnameOf(req) === '/signal' || pathnameOf(req) === '/stream-ws';
  const upstreamPort = isAgent ? AGENT_PORT : (isSignal ? WEBRTC_SIGNAL_PORT : TARGET_PORT);

